export function Flexbox({
  direction = "{{direction}}",
  justify = "{{justify}}",
  align = "{{align}}",
  wrap = {{wrap}},
}) {
  const item = { background: "#BFD9F2", borderRadius: 6, width: 76, height: 40, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="Five flexbox items arranged along a main axis and cross axis, position driven by the controls">
      <div style={{ display: "flex", gap: 8, flexDirection: direction, justifyContent: justify, alignItems: align,
        flexWrap: wrap ? "wrap" : "nowrap", background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 12, minHeight: 140, boxSizing: "border-box" }}>
        <div style={item}>1</div><div style={item}>2</div><div style={item}>3</div><div style={item}>4</div><div style={item}>5</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        main axis: {direction} &middot; justify-content: {justify} &middot; align-items: {align} &middot; wrap: {wrap ? "yes" : "no"}
      </p>
    </div>
  );
}
